       display: flex;
       gap: 0.875rem;
       align-items: flex-start;
       padding: 1rem;
       border: 1px solid var(--border);
       border-radius: 1rem;
       background: #f8fafc;
       transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
     }

